cases.reforce_sql:
SELECT 
    (SELECT COUNT("hex_id_l7") FROM "hex_county_state_zip_crosswalk" WHERE "County" = 'Cameron' AND "hex_id_l7" IN (SELECT "hex_id" FROM "VUL_002" WHERE "sovi" IS NOT NULL)) / 
    (SELECT COUNT("hex_id_l7") FROM "hex_county_state_zip_crosswalk" WHERE "County" = 'Cameron') AS coverage_fraction;

SELECT 
  (SELECT SUM(nri_ealb_AVLN) FROM VUL_003 WHERE hex_id IN (SELECT hex_id_l7 FROM hex_county_state_zip_crosswalk WHERE County = 'Denton')) AS total_building_stock_at_risk,
  (SELECT SUM(nri_eal) FROM VUL_003 WHERE hex_id IN (SELECT hex_id_l7 FROM hex_county_state_zip_crosswalk WHERE County = 'Denton')) AS expected_annual_loss;

SELECT COUNT(*) 
FROM VUL_003 
WHERE nri_ealb_WFIR >= 0.5;

SELECT COUNT(num_facilities) AS total_facilities
FROM (
  SELECT c.hex_id, c.hex_fc_rac_hospital * 1000 AS num_facilities
  FROM CRIT_LIFE_001 c
  JOIN (
    SELECT hex_id_l7 FROM hex_county_state_zip_crosswalk WHERE County = 'Uvalde'
  ) u ON c.hex_id = u.hex_id_l7
  WHERE c.hex_id IN (
    SELECT hex_id_l7 FROM hex_county_state_zip_crosswalk WHERE County = 'Uvalde'
  )
);
